// components.js — 可复用的 UI 原语：提示、模态框、确认框、表格、表单取值。
// 所有视图共用，避免重复实现，保持视图模块高内聚。

export function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

/* ---------- Toast ---------- */
export function toast(message, type = "info", duration = 2800) {
  const root = document.getElementById("toast-root");
  const el = document.createElement("div");
  el.className = `toast ${type}`;
  el.innerHTML = `<span class="toast-msg">${esc(message)}</span>`;
  root.appendChild(el);
  setTimeout(() => {
    el.style.transition = "opacity .25s";
    el.style.opacity = "0";
    setTimeout(() => el.remove(), 260);
  }, duration);
}

/* ---------- Modal ---------- */
export function openModal({ title, body, footer, size, onClose }) {
  const root = document.getElementById("modal-root");
  const backdrop = document.createElement("div");
  backdrop.className = "modal-backdrop";
  const modal = document.createElement("div");
  modal.className = "modal" + (size === "lg" ? " modal-lg" : "");
  modal.innerHTML = `
    <div class="modal-header">
      <h3>${esc(title)}</h3>
      <button class="modal-close" type="button">&times;</button>
    </div>
    <div class="modal-body"></div>
    <div class="modal-footer"></div>`;
  const bodyEl = modal.querySelector(".modal-body");
  const footerEl = modal.querySelector(".modal-footer");
  if (typeof body === "string") bodyEl.innerHTML = body;
  else if (body instanceof Node) bodyEl.appendChild(body);
  if (footer instanceof Node) footerEl.appendChild(footer);
  else if (typeof footer === "string") footerEl.innerHTML = footer;
  else footerEl.remove();

  backdrop.appendChild(modal);
  root.appendChild(backdrop);

  const close = () => {
    backdrop.remove();
    if (onClose) onClose();
  };
  modal.querySelector(".modal-close").addEventListener("click", close);
  backdrop.addEventListener("click", (e) => { if (e.target === backdrop) close(); });
  return { close, bodyEl, footerEl, modal };
}

/* ---------- Confirm ---------- */
export function confirmDialog(message, { title = "请确认", okText = "确定", danger = true } = {}) {
  return new Promise((resolve) => {
    const footer = document.createElement("div");
    const btnCancel = document.createElement("button");
    btnCancel.className = "btn btn-ghost";
    btnCancel.textContent = "取消";
    const btnOk = document.createElement("button");
    btnOk.className = "btn " + (danger ? "btn-danger" : "btn-primary");
    btnOk.textContent = okText;
    footer.append(btnCancel, btnOk);
    const m = openModal({ title, body: `<p style="margin:0">${esc(message)}</p>`, footer });
    btnCancel.onclick = () => { m.close(); resolve(false); };
    btnOk.onclick = () => { m.close(); resolve(true); };
  });
}

/* ---------- Form helpers ---------- */
export function formValues(formEl) {
  const out = {};
  formEl.querySelectorAll("input, select, textarea").forEach((el) => {
    if (!el.name) return;
    out[el.name] = el.type === "checkbox" ? el.checked : el.value.trim();
  });
  return out;
}

export function fillForm(formEl, values) {
  formEl.querySelectorAll("input, select, textarea").forEach((el) => {
    if (!el.name || values[el.name] === undefined || values[el.name] === null) return;
    if (el.type === "checkbox") el.checked = !!values[el.name];
    else el.value = values[el.name];
  });
}

/* ---------- Table ---------- */
// columns: [{ key, title, render?(row), align, className }]
export function renderTable(container, columns, rows) {
  const wrap = document.createElement("div");
  wrap.className = "table-wrap";
  if (!rows || rows.length === 0) {
    wrap.innerHTML = `<div class="table-empty">暂无数据</div>`;
    container.appendChild(wrap);
    return wrap;
  }
  const table = document.createElement("table");
  table.className = "data";
  const thead = `<thead><tr>${columns
    .map((c) => `<th style="${c.align ? `text-align:${c.align}` : ""}">${esc(c.title)}</th>`)
    .join("")}</tr></thead>`;
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    columns.forEach((c) => {
      const td = document.createElement("td");
      if (c.align) td.style.textAlign = c.align;
      if (c.render) td.innerHTML = c.render(row);
      else td.textContent = row[c.key] ?? "";
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.innerHTML = thead;
  table.appendChild(tbody);
  wrap.appendChild(table);
  container.appendChild(wrap);
  return wrap;
}

export function badge(text, variant) {
  return `<span class="badge badge-${variant}">${esc(text)}</span>`;
}

export function loading(container, text = "加载中…") {
  container.innerHTML = `<div class="table-empty">${esc(text)}</div>`;
}

// login.js — 登录 / 注册视图。
import { api } from "./api.js";
import { esc, toast } from "./components.js";

export function renderLogin(onSuccess) {
  const root = document.getElementById("login-root");
  root.innerHTML = `
    <div class="login-card">
      <div class="login-logo">图</div>
      <h2>图书管理系统</h2>
      <p class="login-sub">Library Management System</p>
      <div class="login-tabs">
        <button data-tab="login" class="active">登录</button>
        <button data-tab="register">读者注册</button>
      </div>
      <div id="login-pane">
        <form id="login-form">
          <div class="field">
            <label>用户名</label>
            <input class="input" name="username" required autocomplete="username" placeholder="请输入用户名" />
          </div>
          <div class="field">
            <label>口令</label>
            <input class="input" type="password" name="password" required autocomplete="current-password" placeholder="请输入口令" />
          </div>
          <button class="btn btn-primary btn-block" type="submit">登 录</button>
        </form>
        <p class="form-hint">默认管理员 admin / admin123；读者 reader / reader123</p>
      </div>
      <div id="register-pane" class="hidden">
        <form id="register-form">
          <div class="form-row">
            <div class="field">
              <label>真实姓名</label>
              <input class="input" name="realName" required placeholder="姓名" />
            </div>
            <div class="field">
              <label>手机号</label>
              <input class="input" name="phone" required placeholder="手机号" />
            </div>
          </div>
          <div class="field">
            <label>用户名</label>
            <input class="input" name="username" required placeholder="设置登录用户名" />
          </div>
          <div class="form-row">
            <div class="field">
              <label>口令</label>
              <input class="input" type="password" name="password" required placeholder="设置口令" />
            </div>
            <div class="field">
              <label>确认口令</label>
              <input class="input" type="password" name="password2" required placeholder="再次输入" />
            </div>
          </div>
          <button class="btn btn-primary btn-block" type="submit">注 册</button>
        </form>
      </div>
    </div>`;

  const tabs = root.querySelectorAll(".login-tabs button");
  tabs.forEach((b) =>
    b.addEventListener("click", () => {
      tabs.forEach((x) => x.classList.remove("active"));
      b.classList.add("active");
      const tab = b.dataset.tab;
      root.querySelector("#login-pane").classList.toggle("hidden", tab !== "login");
      root.querySelector("#register-pane").classList.toggle("hidden", tab !== "register");
    })
  );

  root.querySelector("#login-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    const f = e.target;
    const btn = f.querySelector('button[type="submit"]');
    btn.disabled = true;
    try {
      const data = await api.login(f.username.value.trim(), f.password.value);
      toast("登录成功", "success");
      onSuccess(data);
    } catch (err) {
      toast(err.message, "error");
      btn.disabled = false;
    }
  });

  root.querySelector("#register-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    const f = e.target;
    const btn = f.querySelector('button[type="submit"]');
    if (f.password.value !== f.password2.value) {
      toast("两次输入的口令不一致", "error");
      return;
    }
    if (f.password.value.length < 6) {
      toast("口令长度至少 6 位", "error");
      return;
    }
    btn.disabled = true;
    try {
      const data = await api.register({
        username: f.username.value.trim(),
        password: f.password.value,
        realName: f.realName.value.trim(),
        phone: f.phone.value.trim(),
      });
      toast(`注册成功，读者编号 ${data.readerNo}，请登录`, "success", 3600);
      tabs[0].click();
      root.querySelector("#login-form").username.value = f.username.value.trim();
    } catch (err) {
      toast(err.message, "error");
    } finally {
      btn.disabled = false;
    }
  });
}

// net.js — 统一的 fetch 入口。
// 优先使用 Tauri HTTP 插件（请求由 Rust 核心侧发起，可绕过 WebView2 对
// loopback / 跨域 / 混合内容的限制）；在普通浏览器中回退到原生 fetch。
const tauri = typeof window !== "undefined" ? window.__TAURI__ : null;

const pluginFetch = tauri && tauri.http && typeof tauri.http.fetch === "function"
  ? tauri.http.fetch.bind(tauri.http)
  : null;

export const lmsFetch = pluginFetch || window.fetch.bind(window);
export const usingPlugin = !!pluginFetch;
